// Generated from Lanterns and Lies roles.xlsx. Do not edit by hand.
export type Faction="Lanternkeepers"|"Syndicate"|"Cartel"|"Unbound";
export interface RoleDef{id:number;name:string;faction:Faction;type:string;summary:string;ability:string;knowledge:number;killing:number;gameplay:number;drawback:number;total:number;image:string;placeholder:boolean}
export const ROLES:RoleDef[]=[{"id": 1, "name": "Archivist", "faction": "Lanternkeepers", "type": "Investigative", "summary": "You are a wise librarian with knowledge beyond the town.", "ability": "Learn a role:\n• Each Night you learn the name of one role that is alive. If more than one player has that role, you also learn how many are alive.\n• Each Night's role is one you have not learned before.\n• Dead players' roles are no longer shown to you, unless the Priest raises them.\n• Once you know every role still alive, you stop receiving new results.\n• You cannot visit at Night.\n• Deceptive roles can change your results, except the Tailor.", "knowledge": 5, "killing": 0, "gameplay": 0, "drawback": 0, "total": 5, "image": "roles/archivist.webp", "placeholder": false}, {"id": 2, "name": "Detective", "faction": "Lanternkeepers", "type": "Investigative", "summary": "You are a private eye who secretly gathers information.", "ability": "Investigate a target:\n• Each Night you may Investigate one player.\n• You learn their role type: Investigative, Protective, Support, Killing, Power, Deceptive or Chaos.\n• Deceptive roles can change your results.\n• If your target is Disguised, you learn the type of the role they are disguised as.\n• If your target is Framed, they appear Deceptive.\n• If your target is Planted, they appear Killing.", "knowledge": 7, "killing": 0, "gameplay": 0, "drawback": 0, "total": 7, "image": "roles/detective.webp", "placeholder": false}, {"id": 3, "name": "Watchman", "faction": "Lanternkeepers", "type": "Investigative", "summary": "You are an eagle-eyed observer, stealthily camping outside houses to gain information.", "ability": "Keep watch:\n• Each Night you may watch one player's house to see who visits them.\n• You receive the names of everyone who visited your target, except yourself.\n• A player who visits two targets may appear at either house.\n• Deceptive roles can change your results.", "knowledge": 6, "killing": 0, "gameplay": 0, "drawback": 0, "total": 6, "image": "roles/watchman.webp", "placeholder": false}, {"id": 4, "name": "Oracle", "faction": "Lanternkeepers", "type": "Investigative", "summary": "You are a fortune teller who glimpses into the future.", "ability": "Vision:\n• Each Night you may visit one player to include them in your Vision.\n• You receive 3 names, including your target. At least one of them belongs to an opposing faction.\n• Deceptive roles can change your results.\n• Lanternkeepers, and Syndicate members who are Disguised, count as good.\n• Framed Lanternkeepers count as an opposing faction.\n• If no other Lanternkeepers remain, you are told your power can no longer be used.", "knowledge": 5, "killing": 0, "gameplay": 0, "drawback": 0, "total": 5, "image": "roles/oracle.webp", "placeholder": false}, {"id": 5, "name": "Seer", "faction": "Lanternkeepers", "type": "Investigative", "summary": "You are able to see into the hearts of the townsfolk to find out their intentions.", "ability": "Intuition:\n• Each Night you may visit two players to learn whether they are friends or enemies.\n• You cannot target yourself or a Revealed Lanternkeeper.\n• Lanternkeepers, the Martyr and the Outcast are friends with each other.\n• Unbound Killing roles, the Town Crier and the Assassin are enemies with everyone.\n• Syndicate members are friends with other Syndicate members; Cartel members with other Cartel members.\n• Deceptive roles can change your results.\n• The Fence cannot lead you astray.", "knowledge": 6, "killing": 0, "gameplay": 0, "drawback": 0, "total": 6, "image": "roles/seer.webp", "placeholder": false}, {"id": 6, "name": "Constable", "faction": "Lanternkeepers", "type": "Investigative", "summary": "You are the law enforcer of the town forced into hiding from threat of murder.", "ability": "Search a target:\n• Each Night you may Search one player's house for anything suspicious.\n• You learn whether they are Evil or Innocent.\n• Deceptive roles can change your results.\n• A player Disguised as a Lanternkeeper appears Innocent.\n• A Framed player appears Evil.\n• The Martyr and the Outcast appear Innocent.\n• Unbound Killing roles, the Town Crier and the Assassin appear Evil.\n• Syndicate and Cartel members appear Evil.", "knowledge": 5, "killing": 0, "gameplay": 0, "drawback": 0, "total": 5, "image": "roles/constable.webp", "placeholder": false}, {"id": 7, "name": "Spy", "faction": "Lanternkeepers", "type": "Investigative", "summary": "You are a talented watcher who keeps track of evil in the town.", "ability": "Spy on evil:\n• Each Night you learn which players the evil faction (Syndicate or Cartel) visited. You learn who was visited, not who visited them or how many times.\n• A Syndicate member Disguised as a Lanternkeeper is not seen.\n• You cannot visit at Night.\n• Deceptive roles can change your results.", "knowledge": 4, "killing": 0, "gameplay": 0, "drawback": 0, "total": 4, "image": "roles/spy.webp", "placeholder": false}, {"id": 8, "name": "Tracker", "faction": "Lanternkeepers", "type": "Investigative", "summary": "You are a skilled hunter who stalks your prey at night.", "ability": "Follow a target:\n• Each Night you may follow one player to see who they visit.\n• If they visit nobody, you learn that.\n• If they visit two players, they are the Assassin, Seer, Ferryman or Smuggler, or a Cartel member Commanded by the Kingpin. A Tailor's second target does not count as a visit.\n• If they visit a dead player, they are the Medium, Priest or Coroner.\n• If your target was swapped or led astray, you see them visit the player they ended up at.\n• Deceptive roles can change your results.", "knowledge": 6, "killing": 0, "gameplay": 0, "drawback": 0, "total": 6, "image": "roles/tracker.webp", "placeholder": false}, {"id": 9, "name": "Bodyguard", "faction": "Lanternkeepers", "type": "Protective", "summary": "You are an ex-soldier who secretly makes a living by selling protection.", "ability": "Guard a target:\n• Each Night you may protect one player from one attack and strike back at the attacker. You and the attacker both take a Powerful Attack and die unless Healed.\n• If several killers attack your target, you kill one and die; the others can still attack your target.\n• Other Lanternkeeper Protective roles can still protect your target.\n• You only strike visitors who meant harm.\n• You cannot stop or strike back at attacks from the Veteran, another Bodyguard, the Loan Shark's Debt, the Tinkerer's Trigger or the Assassin.\n• A Bodyguard cannot save another Bodyguard who is dying while guarding.", "knowledge": 0, "killing": 5, "gameplay": 5, "drawback": 0, "total": 10, "image": "roles/bodyguard.webp", "placeholder": false}, {"id": 10, "name": "Doctor", "faction": "Lanternkeepers", "type": "Protective", "summary": "You are a surgeon skilled in trauma care who secretly heals people.", "ability": "Heal a target:\n• Each Night you may Heal one player, giving them Powerful Defence.\n• You may Heal yourself once per game.\n• You cannot stop Unstoppable Attacks: the Assassin's hit, the Rogue's guilt, the Loan Shark's Debt or the Tinkerer's Trigger.\n• You may Heal a Bodyguard who would die guarding someone; then only the attacker dies. This also applies if the attacker is Healed and the Bodyguard is not.\n• If you Heal someone the Hollowman visits, you die but your target survives.\n• You cannot target Revealed roles.", "knowledge": 0, "killing": 0, "gameplay": 5, "drawback": 0, "total": 5, "image": "roles/doctor.webp", "placeholder": false}, {"id": 11, "name": "Hunter", "faction": "Lanternkeepers", "type": "Protective", "summary": "You are an intelligent woodsman with a knack for traps.", "ability": "Build a trap:\n• On odd Nights you build traps.\n• You still build your trap if you are Held or led astray.\nSet a trap:\n• On even Nights you may set a trap on one player.\n• If anyone visits the trapped player, the trap goes off on every visitor.\n• Lanternkeeper visitors are Held.\n• If a visitor is Syndicate, Cartel or Unbound Killing, the trap deals a Powerful Attack to one of them and gives your target Powerful Defence against one attack. Syndicate or Cartel visitors are hit before Unbound Killing ones.\n• Your trap stays on its player until it goes off or you set a new one.\n• If you die, your trap is disabled.", "knowledge": 0, "killing": 5, "gameplay": 5, "drawback": 0, "total": 10, "image": "roles/hunter.webp", "placeholder": false}, {"id": 12, "name": "Veteran", "faction": "Lanternkeepers", "type": "Killing", "summary": "You are a paranoid war hero who will shoot anyone who visits you.", "ability": "Go on Alert:\n• You may go on Alert at Night, up to two times per game.\n• While on Alert, you deal a Powerful Attack to every visitor and have Basic Defence.\n• If you are Held, your Alert does not happen.\n• Some roles still act on you even if they die, such as the Ferryman, Smuggler and the Hollowman.\n• You learn how many visitors you killed.\n• Visitors you kill can be saved by a Doctor, but not by a Bodyguard.", "knowledge": 0, "killing": 6, "gameplay": 3, "drawback": 0, "total": 9, "image": "roles/veteran.webp", "placeholder": false}, {"id": 13, "name": "Rogue", "faction": "Lanternkeepers", "type": "Killing", "summary": "You are a former soldier who takes the law into your own hands.", "ability": "Shoot a target:\n• You may Shoot one player at Night, dealing a Basic Attack.\n• You cannot Shoot on the first Night.\n• You may Shoot only once.\n• If you kill a Lanternkeeper, the guilt kills you the next Night with an Unstoppable Attack, even if you are Held, swapped or led astray. Framed or Disguised status makes no difference. If you Shoot a Lanternkeeper but they survive, nothing happens to you.\n• If the Priest raises you, you come back with one bullet.", "knowledge": 0, "killing": 4, "gameplay": 0, "drawback": 0, "total": 4, "image": "roles/rogue.webp", "placeholder": false}, {"id": 14, "name": "Mayor", "faction": "Lanternkeepers", "type": "Power", "summary": "You are the leader of the town.", "ability": "Reveal yourself:\n• At Night you may choose to Reveal yourself as the Mayor. The Narrator confirms it publicly at dawn if it is true.\n• Once Revealed, your vote counts as 3 for the rest of the game.\n• You cannot Reveal on the first Night. If you are Held, have your role swapped, or die that Night, you do not Reveal.\n• Once Revealed, Lanternkeeper Protective roles cannot target you.\n• Once Revealed, you cannot have private conversations or leave the room.", "knowledge": 0, "killing": 2, "gameplay": 6, "drawback": 2, "total": 6, "image": "roles/mayor.webp", "placeholder": false}, {"id": 15, "name": "Judge", "faction": "Lanternkeepers", "type": "Power", "summary": "You are a powerful member of court who ensures that justice prevails.", "ability": "Reveal yourself:\n• At Night you may choose to Reveal yourself as the Judge. The Narrator confirms it publicly at dawn if it is true.\n• Once Revealed, you can Condemn.\n• You cannot Reveal on the first Night. If you are Held, have your role swapped, or die that Night, you do not Reveal.\n• Once Revealed, Lanternkeeper Protective roles cannot target you.\nCondemn a target:\n• If nobody is on Trial during the Voting Phase, you may Condemn a player: they are found Guilty and executed.\n• You may Condemn once per Day for as long as you live.\n• If you Condemn a Lanternkeeper, you are overthrown and die in their place.", "knowledge": 0, "killing": 6, "gameplay": 6, "drawback": 2, "total": 10, "image": "roles/judge.webp", "placeholder": false}, {"id": 16, "name": "Warden", "faction": "Lanternkeepers", "type": "Power", "summary": "You are a prison warden who knows secrets of the town.", "ability": "Patrol a target:\n• Each Night you may Patrol one player.\n• You receive every Night result your target receives.\n• If your target dies that Night, you learn who killed them.\n• You cannot Patrol the same player more than two Nights in a row.\n• Deceptive roles can change your results.", "knowledge": 7, "killing": 0, "gameplay": 2, "drawback": 0, "total": 9, "image": "roles/warden.webp", "placeholder": false}, {"id": 17, "name": "Innkeeper", "faction": "Lanternkeepers", "type": "Support", "summary": "You are a local tavern keeper pouring drinks to all that pass by.", "ability": "Shelter your guests:\n• Everyone who visits you gets Basic Defence for the Night, whatever their faction.\n• If you are Held, you give no defence.\n• You cannot visit at Night.", "knowledge": 0, "killing": 0, "gameplay": 4, "drawback": 0, "total": 4, "image": "roles/innkeeper.webp", "placeholder": false}, {"id": 18, "name": "Locksmith", "faction": "Lanternkeepers", "type": "Support", "summary": "You secure the town by confining threats behind locked doors.", "ability": "Lock a target:\n• Each Night you may Hold one player, so they cannot use their Night ability.\n• The Fence can lead your Hold astray onto a neighbour, and the Pawnbroker can draw it onto himself.\n• Hold-immune roles, such as the Enforcer and the Quartermaster, are not affected. You cannot be Held, and you cannot Hold another Locksmith.\n• If you Hold the Butcher, or the Hollowman on a clear Night, you are attacked.", "knowledge": 0, "killing": 0, "gameplay": 5, "drawback": 0, "total": 5, "image": "roles/locksmith.webp", "placeholder": false}, {"id": 19, "name": "Medium", "faction": "Lanternkeepers", "type": "Support", "summary": "You are a medium gathering power from the unfinished business of the dead.", "ability": "Channel the dead:\n• Once per game, at Night, you may choose a dead player. If they were a Lanternkeeper, you become their role for the rest of the game, with a fresh start: one bullet for the Rogue, two Alerts for the Veteran, one self-Heal for the Doctor.\n• It fails on anyone who was not a Lanternkeeper, and on any Power role. You are told it failed.\n• If you and the Priest choose the same dead player, you still become their role.", "knowledge": 1, "killing": 2, "gameplay": 6, "drawback": 0, "total": 9, "image": "roles/medium.webp", "placeholder": false}, {"id": 20, "name": "Priest", "faction": "Lanternkeepers", "type": "Support", "summary": "You are a powerful priest that can raise the true-hearted dead.", "ability": "Raise the dead:\n• Once per game you may raise one dead player. They return with their abilities intact, except the Rogue, who returns with one bullet.\n• If you and the Coroner choose the same dead player, your raising stops the Coroner using them that Night.\n• You may raise any role.\n• Raised players come back clean: no Debt, Planted explosive, Frame, bribe or other effect from before their death carries over.", "knowledge": 0, "killing": 0, "gameplay": 8, "drawback": 0, "total": 8, "image": "roles/priest.webp", "placeholder": false}, {"id": 21, "name": "Ferryman", "faction": "Lanternkeepers", "type": "Support", "summary": "Your job is to transport people without asking any questions.", "ability": "Swap targets:\n• Each Night you may swap two players (you can include yourself).\n• Everyone who visits one of them visits the other instead.\n• Swapping does not save anyone from the Tinkerer's Trigger: every Planted player still dies.\n• The Fence cannot lead you astray.\n• You cannot be Held.\n• Swapped players are told; their visitors are not.\n• If your swap makes a player visit themselves, they use their ability on themselves. If you redirect Butcher or Hollowman to their own house they will attack you.\n• Your swap goes first: if the Smuggler chooses a player you swapped, the Smuggler's swap fails.", "knowledge": 0, "killing": 1, "gameplay": 7, "drawback": 0, "total": 8, "image": "roles/ferryman.webp", "placeholder": false}, {"id": 22, "name": "Mobster", "faction": "Syndicate", "type": "Killing", "summary": "You are a member of organized crime, trying to work your way to the top.", "ability": "Attack a target:\n• You know every Syndicate member.\n• Each Night you may choose a player to attack. If the Godfather chooses someone else, you follow the Godfather, unless the Godfather is Held.\n• If the Godfather dies, you become the Godfather. You cannot become Godfather if there was none at the start of the game.\n• If you die and there is no living Godfather, a random Syndicate member becomes the new Mobster.", "knowledge": 0, "killing": 6, "gameplay": 0, "drawback": 0, "total": 6, "image": "roles/mobster.webp", "placeholder": false}, {"id": 23, "name": "Godfather", "faction": "Syndicate", "type": "Power", "summary": "You are the leader of organized crime.", "ability": "Order a hit:\n• You know every Syndicate member and their role.\n• Each Night you may choose a player to attack. Your choice overrides the Mobster's, if one is alive.\n• If you are Held, the Mobster attacks their own choice. If they chose nobody or are Held too, nobody is attacked.\n• If the Mobster is Held, dead or not in the game, you carry out the attack yourself.\n• If the Mobster carries out your attack, investigators see the Mobster's visit, not yours.\n• You have Basic Defence, so attacks such as the Rogue's, the Butcher's or your own family's (if redirected) fail.\n• You have Detection Immunity: the Constable, the Oracle and the Seer read you as a Lanternkeeper. The Detective and the Spy are unaffected.", "knowledge": 3, "killing": 7, "gameplay": 0, "drawback": 0, "total": 10, "image": "roles/godfather.webp", "placeholder": false}, {"id": 24, "name": "Enforcer", "faction": "Syndicate", "type": "Support", "summary": "You intimidate your targets with brute force.", "ability": "Blackmail a target:\n• You know every Syndicate member.\n• Each Night you may Hold one player, so they cannot use their Night ability.\n• The Fence can lead your Hold astray onto a neighbour, and the Pawnbroker can draw it onto himself.\n• Hold-immune roles, such as the Locksmith, are not affected. You cannot be Held, and you cannot Hold another Enforcer.\n• You cannot Hold abilities used during the Day.\n• If you Hold the Butcher, or the Hollowman on a clear Night, they attack you.", "knowledge": 0, "killing": 0, "gameplay": 5, "drawback": 0, "total": 5, "image": "roles/enforcer.webp", "placeholder": false}, {"id": 25, "name": "Informant", "faction": "Syndicate", "type": "Support", "summary": "You are a corrupted investigator who gathers information for the Syndicate.", "ability": "Pull the file:\n• You know every Syndicate member.\n• Each Night you may check one player and learn their exact role.\n• A Planted player appears as the Tinkerer.\n• Framed and Disguised players still appear as their true role.", "knowledge": 8, "killing": 0, "gameplay": 0, "drawback": 0, "total": 8, "image": "roles/informant.webp", "placeholder": false}, {"id": 26, "name": "Fence", "faction": "Syndicate", "type": "Support", "summary": "You are a dealer in stolen goods who leads people astray.", "ability": "Lead astray:\n• You know every Syndicate member.\n• Each Night you may lead one player astray: they visit a living neighbour instead of their target (a dead neighbour if they are the Priest).\n• You only visit your first target, not the neighbour they end up at.\n• You do not learn their role or what happened at the neighbour's house.\n• If you lead a Locksmith, Enforcer or Quartermaster astray, their Hold lands on the neighbour, even if it was meant for you.\n• You cannot lead astray the Seer, the Ferryman, the Assassin or anyone who cannot visit.", "knowledge": 0, "killing": 0, "gameplay": 6, "drawback": 0, "total": 6, "image": "roles/fence.webp", "placeholder": false}, {"id": 27, "name": "Tailor", "faction": "Syndicate", "type": "Deceptive", "summary": "You are a master of disguise who can make people appear to be someone they are not.", "ability": "Disguise a target:\n• You know every Syndicate member.\n• Each Night you may disguise a living Syndicate member as any player outside the Syndicate, alive or dead. The Constable, Detective, Watchman, Oracle, Seer and Spy get misleading results.\n• Only your visit to the Syndicate member counts as a visit; the player they are disguised as is not visited.\n• A Watchman sees the disguised-as player visiting, not the Syndicate member.\n• If someone is both Planted and Disguised, the Detective still sees the Planted result.\n• You may disguise yourself; that counts as visiting yourself.\n• The disguise does not fool the Informant.\n• The disguise lasts until the next Night.", "knowledge": 0, "killing": 0, "gameplay": 5, "drawback": 0, "total": 5, "image": "roles/tailor.webp", "placeholder": false}, {"id": 28, "name": "Framer", "faction": "Syndicate", "type": "Deceptive", "summary": "You are a skilled counterfeiter who manipulates information.", "ability": "Frame a target:\n• You know every Syndicate member.\n• Each Night you may Frame one player, so they look evil.\n• A Frame takes priority over the Tinkerer's Plant.\n• Framed players look like they are not Lanternkeepers to the Seer, Detective, Oracle and Constable.", "knowledge": 0, "killing": 0, "gameplay": 5, "drawback": 0, "total": 5, "image": "roles/framer.webp", "placeholder": false}, {"id": 29, "name": "Harbour Master", "faction": "Cartel", "type": "Power", "summary": "You are the local docks manager and every crate that comes up the river passes through your hands.", "ability": "Bring a shipment:\n• You know every Cartel member and their role.\n• Each Night you may bring in one illegal shipment: Passage on odd Nights, Guns on even Nights.\n• Passage: choose any player and ship them out for the Day. At dawn the town is told they have been sent away; the next Day they cannot vote or be voted for. Only the Judge can override this: the Judge can still Condemn them.\n• Guns: choose a Cartel member. That Night they also deal a Basic Attack to the player they visit, on top of their ability. If you are the only Cartel member alive, you may take the Guns yourself and deal a Basic Attack to one player.\n• You have Basic Defence.\n• You have Detection Immunity: the Constable, the Oracle and the Seer read you as a Lanternkeeper. The Detective and the Spy are unaffected.", "knowledge": 3, "killing": 5, "gameplay": 7, "drawback": 0, "total": 15, "image": "roles/harbour-master.webp", "placeholder": false}, {"id": 30, "name": "Loan Shark", "faction": "Cartel", "type": "Power", "summary": "You are a loan shark, who lends blood money to Lanternkeepers.", "ability": "Collect a debt:\n• You know every Cartel member and their role.\n• Each Night you may visit one player and put them in Debt. At the start of the next Night, before they choose their action, they are told they owe the Loan Shark, but not who the Loan Shark is. That Night is their Collection Night.\n• On their Collection Night, a player in Debt must visit you to pay. Paying is their whole action that Night. If they pay, the Debt is cleared. If not, they die at the end of that Night (Unstoppable Attack).\n• A player in Debt who is Held cannot pay.\n• A player in Debt who cannot visit at Night is still asked to pay on their Collection Night and chooses one player to pay. If they choose you, the Debt is cleared.\n• You learn the exact role of every player you visit and every player who visits you.\n• Anyone who visits you while not in Debt is put in Debt, and told the same way at the start of the next Night.\n• If you die, every Debt is cleared.\n• You cannot put Cartel members in Debt.\n• You have Detection Immunity: the Constable, the Oracle and the Seer read you as a Lanternkeeper. The Detective and the Spy are unaffected.", "knowledge": 9, "killing": 7, "gameplay": 7, "drawback": 5, "total": 18, "image": "roles/loan-shark.webp", "placeholder": false}, {"id": 31, "name": "Kingpin", "faction": "Cartel", "type": "Power", "summary": "You are the secret leader. Nobody has seen your face, not even the people who work for you.", "ability": "Command a target:\n• You know every Cartel member and their role. The rest of the Cartel know there is a Kingpin, but not who.\n• Each Night you may choose one Cartel member. That Night they use their ability twice, each time on a different target (or targets).\n• You cannot Command the Foreman or the Swindler.\n• While at least one other Cartel member is alive, you have Powerful Defence.\n• You have Detection Immunity: the Constable, the Oracle and the Seer read you as a Lanternkeeper. The Detective and the Spy are unaffected.\nNew crew:\n• Replaces Command a target once you are the only Cartel member alive.\n• You have no defence.\n• Once per game, at Night, you may recruit one player. They become the Foreman and are told what they now are.\n• Recruiting a Power role or an Unbound Killing role fails.", "knowledge": 3, "killing": 3, "gameplay": 9, "drawback": 0, "total": 15, "image": "roles/kingpin.webp", "placeholder": false}, {"id": 32, "name": "Foreman", "faction": "Cartel", "type": "Killing", "summary": "You are the foreman of the dock gangs, and you remove anyone in the Cartel's way.", "ability": "Attack a target:\n• You know every Cartel member, except the Kingpin.\n• Each Night you may attack one player with a Basic Attack.\n• If you die, a random Cartel member becomes the new Foreman when there is no living Cartel Power role, or when the Power role is the Kingpin. The Kingpin never becomes the Foreman.", "knowledge": 0, "killing": 6, "gameplay": 0, "drawback": 0, "total": 6, "image": "roles/foreman.webp", "placeholder": false}, {"id": 33, "name": "Quartermaster", "faction": "Cartel", "type": "Support", "summary": "You are the keeper of the Cartel's ship cargo.", "ability": "Hold a target:\n• You know every Cartel member, except the Kingpin.\n• Each Night you may Hold one player below deck, so they cannot use their Night ability. The Held player has Powerful Defence that Night.\n• The Fence can lead your Hold astray onto a neighbour, and the Pawnbroker can draw it onto himself.\n• Hold-immune roles, such as the Locksmith, are not affected. You cannot be Held, and you cannot Hold another Quartermaster.\n• You cannot Hold abilities used during the Day.\n• If you Hold the Butcher, or the Hollowman on a clear Night, they attack you.", "knowledge": 0, "killing": 0, "gameplay": 6, "drawback": 0, "total": 6, "image": "roles/quartermaster.webp", "placeholder": false}, {"id": 34, "name": "Paymaster", "faction": "Cartel", "type": "Support", "summary": "You are the Cartel's paymaster, and you buy the town's votes.", "ability": "Buy a vote:\n• You know every Cartel member, except the Kingpin.\n• Each Night you may bribe one player.\n• The next Day your vote counts as two and theirs counts as zero.\n• If you bribe a Power role, the bribe fails and both votes count as normal.", "knowledge": 0, "killing": 1, "gameplay": 6, "drawback": 0, "total": 7, "image": "roles/paymaster.webp", "placeholder": false}, {"id": 35, "name": "Coroner", "faction": "Cartel", "type": "Support", "summary": "You are the town coroner, and you learn the secrets of the dead.", "ability": "Examine the dead:\n• You know every Cartel member, except the Kingpin.\n• Each Night you may choose a dead player and use their ability on a target you choose.\n• You learn the dead player's role.\n• If the Priest raises the same dead player that Night, you cannot use them.\n• You cannot use a dead player's Day ability.", "knowledge": 3, "killing": 2, "gameplay": 6, "drawback": 0, "total": 11, "image": "roles/coroner.webp", "placeholder": false}, {"id": 36, "name": "Notary", "faction": "Cartel", "type": "Support", "summary": "You are the port's notary, and you check everyone's papers.", "ability": "Certify a target:\n• You know every Cartel member, except the Kingpin.\n• Each Night you may visit one player and learn their exact role.\n• A Planted player appears as the Tinkerer.", "knowledge": 8, "killing": 0, "gameplay": 0, "drawback": 0, "total": 8, "image": "roles/notary.webp", "placeholder": false}, {"id": 37, "name": "Forger", "faction": "Cartel", "type": "Deceptive", "summary": "You are a forger of papers and reports.", "ability": "Forge the results:\n• You know every Cartel member, except the Kingpin.\n• Each Night you may visit one player.\n• If they are an Investigative role, whatever they learn that Night is false: the Narrator gives them a wrong result. For the Watchman and the Tracker, this means wrong names.\n• On a Fog Night, a forged result is still false.", "knowledge": 0, "killing": 0, "gameplay": 5, "drawback": 0, "total": 5, "image": "roles/forger.webp", "placeholder": false}, {"id": 38, "name": "Smuggler", "faction": "Cartel", "type": "Deceptive", "summary": "You are a smuggler who moves people where they shouldn't be.", "ability": "Swap targets:\n• You know every Cartel member, except the Kingpin.\n• Each Night you may swap two players (you can include yourself).\n• Everyone who visits one of them visits the other instead.\n• Swapping does not save anyone from the Tinkerer's Trigger: every Planted player still dies.\n• You cannot be Held.\n• Swapped players are told; their visitors are not.\n• If your swap makes a player visit themselves, they use their ability on themselves. If you redirect Butcher or Hollowman to their own house they will attack you.\n• If you choose a player the Ferryman has already swapped that Night, your swap fails. The Ferryman's swap goes first.", "knowledge": 0, "killing": 1, "gameplay": 7, "drawback": 0, "total": 8, "image": "roles/smuggler.webp", "placeholder": false}, {"id": 39, "name": "Pawnbroker", "faction": "Cartel", "type": "Deceptive", "summary": "You are a pawnbroker who draws people to your counter.", "ability": "Draw a visitor:\n• You know every Cartel member, except the Kingpin.\n• Each Night you may choose one player.\n• Their visit comes to you instead of their target, and they are not told.\n• Their ability is used on you.\n• If you draw a Locksmith, Enforcer or Quartermaster, their Hold lands on you.\n• You cannot draw a player who visits two targets.", "knowledge": 0, "killing": 0, "gameplay": 4, "drawback": 0, "total": 4, "image": "roles/pawnbroker.webp", "placeholder": false}, {"id": 40, "name": "Swindler", "faction": "Cartel", "type": "Deceptive", "summary": "You are a swindler who swaps people's roles.", "ability": "Swap two roles:\n• You know every Cartel member, except the Kingpin.\n• Once per game, at Night, you may swap the roles of any two players outside the Cartel. If either turns out to be Cartel, your swap fails.\n• You cannot swap a Revealed player. Your swap also fails if either player is recruited by the Kingpin or dies that Night.\n• A Mayor or Judge whose role you swap does not Reveal that Night.\n• Each wakes with the other's role and is told what they now are, but not who had it before.\n• Faction, win condition, ability and its remaining uses go with the role. Statuses, such as Debt, Planted, Framed or Held, stay with the player.", "knowledge": 0, "killing": 0, "gameplay": 8, "drawback": 0, "total": 8, "image": "roles/swindler.webp", "placeholder": false}, {"id": 41, "name": "Tinkerer", "faction": "Unbound", "type": "Killing", "summary": "You are a tinkerer who repairs the town's houses and secretly plants explosives in them.", "ability": "Plant:\n• Each Night you may plant an explosive in one player's house. They are not told they are Planted.\n• Everyone who visits you is Planted too, even if you are Held. You also learn who visited you.\n• You have Basic Defence all game.\n• Planting is not a harmful visit.\n• Planted players look evil to the Constable, the Oracle, the Seer and the Detective.\nTrigger:\n• Visit yourself to Trigger: every Planted player takes an Unstoppable Attack.", "knowledge": 4, "killing": 8, "gameplay": 4, "drawback": 0, "total": 16, "image": "roles/tinkerer.webp", "placeholder": false}, {"id": 42, "name": "Butcher", "faction": "Unbound", "type": "Killing", "summary": "You are a psychotic criminal who wants everyone to die.", "ability": "Murder a target:\n• Each Night you may attack one player with a Basic Attack.\n• You cannot visit on the first Night.\n• You automatically attack anyone who Holds you.\n• You have Basic Defence.\n• If you successfully Murder two Nights in a row, you Rampage at your target's house instead. A Night without a Murder resets the streak.", "knowledge": 0, "killing": 10, "gameplay": 2, "drawback": 0, "total": 12, "image": "roles/butcher.webp", "placeholder": false}, {"id": 43, "name": "Hollowman", "faction": "Unbound", "type": "Killing", "summary": "You are the lamplighter who walked into the Gloam after a lost child and came back alone.", "ability": "Hollow a house (clear Nights):\n• On clear (odd) Nights you may choose a player. You deal a Powerful Attack to them and everyone who visits them, and you have Powerful Defence that Night.\nSwallow the lights (Fog Nights):\n• On Fog Nights (every even Night), you cannot attack however, every information result that night is random, for every faction: it may be right or wrong. Nobody's choices or visits change.", "knowledge": 0, "killing": 8, "gameplay": 10, "drawback": 0, "total": 18, "image": "roles/hollowman.webp", "placeholder": false}, {"id": 44, "name": "Assassin", "faction": "Unbound", "type": "Chaos", "summary": "You are a contracted killer, hired to assassinate your targets.", "ability": "Take the contract:\n• You are given the names of 2 roles in the game.\n• Each Night you guess which players have those roles.\n• Your two targets are always in opposing factions.\n• You have Basic Defence.\n• If you visit both targets on the same Night, they each take an Unstoppable Attack and you win.\n• Your targets may already be dead; you still have to name both correctly on the same Night.\n• Once you have found both, you win whatever happens to you.", "knowledge": 2, "killing": 4, "gameplay": 1, "drawback": 0, "total": 7, "image": "roles/assassin.webp", "placeholder": false}, {"id": 45, "name": "Town Crier", "faction": "Unbound", "type": "Chaos", "summary": "You are the town crier, and you will turn the whole town against one person.", "ability": "Turn the town:\n• At the start of the game you are given a target. You win if the town votes them out during the Day.\n• You have Basic Defence.\n• Your target is always a Lanternkeeper, but never a Lanternkeeper Power role. If the Kingpin recruits them, your target does not change.\n• Once your target is voted out Guilty, you win.\n• If your target dies any other way, you become the Martyr: you win if you are voted out yourself.\n• If the Swindler hands your role to your own target, they become the Martyr at once.", "knowledge": 1, "killing": 0, "gameplay": 3, "drawback": 0, "total": 4, "image": "roles/town-crier.webp", "placeholder": false}, {"id": 46, "name": "Martyr", "faction": "Unbound", "type": "Chaos", "summary": "You are a guilty soul who wants the town to put you to death.", "ability": "Be voted out:\n• You win if you are voted out during the Day.\n• When you are voted out, your role is Revealed to everyone.\n• You appear Innocent to the Constable and as a Lanternkeeper to the Seer and the Oracle.", "knowledge": 0, "killing": 0, "gameplay": 1, "drawback": 0, "total": 1, "image": "roles/martyr.webp", "placeholder": false}, {"id": 47, "name": "Outcast", "faction": "Unbound", "type": "Chaos", "summary": "You are a banished townsperson trying to survive.", "ability": "Survive:\n• You win if you are alive at the end of the game.\n• You have Basic Defence.\n• You cannot visit at Night.\n• You appear Innocent to the Constable and as a Lanternkeeper to the Seer and the Oracle.", "knowledge": 0, "killing": 0, "gameplay": 0, "drawback": 0, "total": 0, "image": "roles/outcast.webp", "placeholder": false}];
